1	import { NextResponse } from "next/server";
2	import { db } from "@/lib/db";
3	
4	export const runtime = "nodejs";
5	
6	/**
7	 * Page-view capture endpoint. Called fire-and-forget by <VisitTracker/> mounted
8	 * in the marketing layout and the portal Shell. It records a single `Visit` row
9	 * and MUST NOT throw or block the caller — analytics is strictly best-effort.
10	 *
11	 * The client IP is taken only from `x-forwarded-for` (nginx sets it); we never
12	 * trust a body-supplied IP. Bots are dropped by a coarse UA check. The visit
13	 * "kind" (marketing vs portal) comes from a `?k=` query param the mounter sets.
14	 */
15	
16	const BOT_RE =
17	  /bot|crawl|spider|slurp|bingpreview|mediapartners|adsbot|facebookexternalhit|embedly|quora|pinterest|redditbot|whatsapp|telegrambot|discordbot|slackbot|semrush|ahrefs|mj12|dotbot|petalbot|yandex|baidu|duckduckbot|headless|phantomjs|python-requests|python-urllib|go-http|libwww|curl\/|wget\/|okhttp|axios\/|node-fetch|lighthouse|pagespeed|gtmetrix|pingdom|uptimerobot|statuscake|monitor|preview|scrapy/i;
18	
19	/** First hop of x-forwarded-for is the real client (nginx appends downstream). */
20	function clientIp(req: Request): string {
21	  const xff = req.headers.get("x-forwarded-for") ?? "";
22	  const first = xff.split(",")[0]?.trim();
23	  return first || "unknown";
24	}
25	
26	export async function POST(req: Request) {
27	  try {
28	    const url = new URL(req.url);
29	    const kindParam = url.searchParams.get("k");
30	    const kind = kindParam === "portal" ? "portal" : "marketing";
31	
32	    const ua = (req.headers.get("user-agent") ?? "").slice(0, 400);
33	    // Silently accept but skip obvious bots and empty UAs.
34	    if (!ua || BOT_RE.test(ua)) {
35	      return NextResponse.json({ ok: true });
36	    }
37	
38	    const body = (await req.json().catch(() => ({}))) as {
39	      path?: unknown;
40	      referrer?: unknown;
41	    };
42	    const path =
43	      typeof body.path === "string" && body.path ? body.path.slice(0, 300) : "/";
44	    let referrer =
45	      typeof body.referrer === "string" && body.referrer
46	        ? body.referrer.slice(0, 400)
47	        : null;
48	    // Drop same-origin referrers — they're just internal navigation noise.
49	    if (referrer) {
50	      try {
51	        if (new URL(referrer).host === url.host) referrer = null;
52	      } catch {
53	        /* keep opaque referrer strings as-is */
54	      }
55	    }
56	
57	    await db.visit.create({
58	      data: { ip: clientIp(req), path, referrer, ua, kind },
59	    });
60	  } catch {
61	    // Never surface capture failures to the page.
62	  }
63	  return NextResponse.json({ ok: true });
64	}
