1	"use server";
2	
3	import { revalidatePath } from "next/cache";
4	import { createHash, randomBytes } from "node:crypto";
5	import bcrypt from "bcryptjs";
6	import { db } from "./db";
7	import { requireUser } from "./auth";
8	import { generateSecret, otpauthURL, verifyTOTP } from "./totp";
9	
10	/**
11	 * Two-factor authentication (TOTP) server actions.
12	 *
13	 * Enrolment flow:
14	 *   1. `beginTotpEnrollment()` -> generates a secret, stores it (totpEnabled
15	 *      stays false), and returns the otpauth URI + secret for the UI to show.
16	 *   2. `confirmTotpEnrollment(code)` -> user enters a code from their app; on
17	 *      success `totpEnabled` flips true and backup codes are generated.
18	 *   3. `disableTotp(codeOrPassword)` -> requires a valid TOTP/backup code OR
19	 *      the account password.
20	 *
21	 * Backup codes are one-time; only their sha256 hashes are stored.
22	 */
23	
24	function hashCode(code: string): string {
25	  return createHash("sha256").update(code.trim().toLowerCase()).digest("hex");
26	}
27	
28	/** Generate N human-friendly one-time backup codes (plaintext, for display). */
29	function makeBackupCodes(n = 10): string[] {
30	  return Array.from({ length: n }, () => {
31	    const raw = randomBytes(5).toString("hex"); // 10 hex chars
32	    return `${raw.slice(0, 5)}-${raw.slice(5)}`;
33	  });
34	}
35	
36	/**
37	 * Verify a submitted code for a user: passes if it matches TOTP OR consumes a
38	 * valid one-time backup code (which is then removed). Intended to be called by
39	 * the login flow once the password check succeeds.
40	 */
41	export async function verifyTotpForUser(userId: string, code: string): Promise<boolean> {
42	  const user = await db.user.findUnique({ where: { id: userId } });
43	  if (!user || !user.totpEnabled || !user.totpSecret) return false;
44	
45	  if (verifyTOTP(user.totpSecret, code)) return true;
46	
47	  // Fall back to consuming a backup code.
48	  const submitted = hashCode(code);
49	  const idx = user.backupCodes.indexOf(submitted);
50	  if (idx === -1) return false;
51	  const remaining = user.backupCodes.filter((_, i) => i !== idx);
52	  await db.user.update({ where: { id: user.id }, data: { backupCodes: remaining } });
53	  await db.auditLog.create({ data: { userId: user.id, action: "user.2fa_backup_code_used" } });
54	  return true;
55	}
56	
57	/** Step 1: create (but do not yet activate) a TOTP secret. */
58	export async function beginTotpEnrollment(): Promise<{ secret: string; otpauthUrl: string }> {
59	  const user = await requireUser();
60	  const secret = generateSecret();
61	  await db.user.update({
62	    where: { id: user.id },
63	    data: { totpSecret: secret, totpEnabled: false },
64	  });
65	  return { secret, otpauthUrl: otpauthURL(secret, user.email) };
66	}
