68	/** Step 2: confirm enrolment with a code; activates 2FA and returns backup codes. */
69	export async function confirmTotpEnrollment(
70	  prev: unknown,
71	  formData: FormData,
72	): Promise<{ error?: string; ok?: boolean; backupCodes?: string[] }> {
73	  const user = await requireUser();
74	  const code = String(formData.get("code") ?? "");
75	  if (!user.totpSecret) return { error: "Start enrolment first." };
76	  if (!verifyTOTP(user.totpSecret, code)) return { error: "That code is incorrect. Try again." };
77	
78	  const backupCodes = makeBackupCodes();
79	  await db.user.update({
80	    where: { id: user.id },
81	    data: { totpEnabled: true, backupCodes: backupCodes.map(hashCode) },
82	  });
83	  await db.auditLog.create({ data: { userId: user.id, action: "user.2fa_enabled" } });
84	  revalidatePath("/dashboard/settings");
85	  return { ok: true, backupCodes };
86	}
