88	/** Regenerate backup codes (invalidates any previous ones). Requires a valid TOTP code. */
89	export async function regenerateBackupCodes(
90	  prev: unknown,
91	  formData: FormData,
92	): Promise<{ error?: string; backupCodes?: string[] }> {
93	  const user = await requireUser();
94	  const code = String(formData.get("code") ?? "");
95	  if (!user.totpEnabled || !user.totpSecret) return { error: "2FA is not enabled." };
96	  if (!verifyTOTP(user.totpSecret, code)) return { error: "That code is incorrect." };
97	  const backupCodes = makeBackupCodes();
98	  await db.user.update({ where: { id: user.id }, data: { backupCodes: backupCodes.map(hashCode) } });
99	  await db.auditLog.create({ data: { userId: user.id, action: "user.2fa_backup_regenerated" } });
100	  return { backupCodes };
101	}
102	
103	/** Disable 2FA. Requires a valid TOTP/backup code OR the account password. */
104	export async function disableTotp(
105	  prev: unknown,
106	  formData: FormData,
107	): Promise<{ error?: string; ok?: boolean }> {
108	  const user = await requireUser();
109	  const proof = String(formData.get("proof") ?? "");
110	  if (!user.totpEnabled) return { error: "2FA is not enabled." };
111	
112	  const codeValid =
113	    (user.totpSecret ? verifyTOTP(user.totpSecret, proof) : false) ||
114	    (await verifyTotpForUser(user.id, proof));
115	  const passwordValid = proof.length > 0 && (await bcrypt.compare(proof, user.passwordHash));
116	  if (!codeValid && !passwordValid) {
117	    return { error: "Enter a valid authenticator code, backup code, or your password." };
118	  }
119	
120	  await db.user.update({
121	    where: { id: user.id },
122	    data: { totpEnabled: false, totpSecret: null, backupCodes: [] },
123	  });
124	  await db.auditLog.create({ data: { userId: user.id, action: "user.2fa_disabled" } });
125	  revalidatePath("/dashboard/settings");
126	  return { ok: true };
127	}
