1	import { db } from "./db";
2	import { pve, node as primaryNode, pveFor } from "./proxmox";
3	import type { Node } from "@prisma/client";
4	
5	/**
6	 * Shared, READ-ONLY monitoring helpers for Nxeon.
7	 *
8	 * Everything here is safe to call from server components (status page, admin
9	 * monitoring) and from the worker sweep (`worker/monitor.ts`). No mutations,
10	 * no secrets in the returned shapes — the public /status page renders off the
11	 * same `getHealth()` logic the API exposes.
12	 *
13	 * Proxmox access is strictly read-only: `GET /nodes/{node}/status` and
14	 * `GET /nodes/{node}/storage/{storage}/status` (+ backup content listing).
15	 */
16	
17	export type CompStatus = "operational" | "degraded" | "down";
18	export type Component = { status: CompStatus; detail: string };
19	
20	export type HealthReport = {
21	  web: Component;
22	  db: Component;
23	  worker: Component;
24	  proxmox: Component;
25	  checkedAt: string;
26	};
27	
28	// ---- Thresholds (env-overridable) ---------------------------------------
29	
30	/** Worker is expected to touch the queue within this window; older QUEUED work ⇒ down. */
31	export const WORKER_STALE_MS = Number(process.env.NXEON_WORKER_STALE_MS ?? 2 * 60_000);
32	/** A Job sitting in RUNNING longer than this is considered stuck. */
33	export const STUCK_JOB_MS = Number(process.env.NXEON_STUCK_JOB_MS ?? 15 * 60_000);
34	/** Storage usage above this fraction trips a disk-capacity alert. */
35	export const DISK_WARN_RATIO = Number(process.env.NXEON_DISK_WARN_RATIO ?? 0.85);
36	/** Node RAM usage above this fraction trips an alert. */
37	export const RAM_WARN_RATIO = Number(process.env.NXEON_RAM_WARN_RATIO ?? 0.9);
38	/** No fresh backup within this window ⇒ backups look stale. */
39	export const BACKUP_STALE_MS = Number(process.env.NXEON_BACKUP_STALE_MS ?? 48 * 60 * 60_000);
40	/** QUEUED backlog at/above this depth trips an alert. */
41	export const QUEUE_BACKLOG_ALERT = Number(process.env.NXEON_QUEUE_BACKLOG_ALERT ?? 25);
42	
43	// ---- Small formatters ----------------------------------------------------
44	
45	/** Compact human age from a millisecond duration. */
46	export function fmtAge(ms: number): string {
47	  if (ms < 0) ms = 0;
48	  const m = Math.floor(ms / 60_000);
49	  if (m < 1) return "just now";
50	  if (m < 60) return `${m}m`;
51	  const h = Math.floor(m / 60);
52	  if (h < 24) return `${h}h`;
53	  const d = Math.floor(h / 24);
54	  return `${d}d ${h % 24}h`;
55	}
56	
57	// ---- Proxmox targets (read-only) ----------------------------------------
58	
59	type PveTarget = {
60	  label: string;
61	  pveNode: string;
62	  get: (path: string, params?: Record<string, any>) => Promise<any>;
63	  /** Distinct storages worth watching on this node. */
64	  storages: string[];
65	};
66	
67	/**
68	 * Resolve the set of Proxmox nodes to poll. Prefers explicit `Node` rows
69	 * (multi-node), and falls back to the env-configured primary when none exist.
70	 */
71	export async function nodeTargets(): Promise<PveTarget[]> {
72	  const nodes = await db.node.findMany({
73	    where: { enabled: true },
74	    orderBy: [{ isPrimary: "desc" }, { createdAt: "asc" }],
75	  });
76	  if (nodes.length === 0) {
77	    return [
78	      {
79	        label: primaryNode || "primary",
80	        pveNode: primaryNode,
81	        get: (p, pp) => pve.get(p, pp),
82	        storages: ["vmdata", "backup"],
83	      },
84	    ];
85	  }
86	  return nodes.map((n: Node) => {
87	    const client = pveFor({
88	      apiUrl: n.apiUrl,
89	      pveNode: n.pveNode,
90	      tokenId: n.tokenId,
91	      tokenSecret: n.tokenSecret,
92	    });
93	    const storages = [n.storageNvme, n.storageHdd, "backup"].filter(
94	      (v, i, a) => v && a.indexOf(v) === i
95	    );
96	    return { label: n.name, pveNode: n.pveNode, get: client.get, storages };
97	  });
98	}
