1	/**
2	 * Lightweight, dependency-free error logging.
3	 * Always writes a structured line to stderr (captured by journald); if
4	 * NXEON_ERROR_WEBHOOK is set, also POSTs a compact alert (best-effort).
5	 * Swap in Sentry later by adding a call here — this is the single choke point.
6	 */
7	type Level = "error" | "warn" | "info";
8	
9	export async function logEvent(
10	  level: Level,
11	  context: string,
12	  detail: Record<string, unknown> = {},
13	): Promise<void> {
14	  const line = {
15	    ts: new Date().toISOString(),
16	    level,
17	    context,
18	    ...detail,
19	    env: process.env.NXEON_ENV ?? "production",
20	  };
21	  const serialized = JSON.stringify(line);
22	  if (level === "error") console.error(`[nxeon] ${serialized}`);
23	  else if (level === "warn") console.warn(`[nxeon] ${serialized}`);
24	  else console.log(`[nxeon] ${serialized}`);
25	
26	  const webhook = process.env.NXEON_ERROR_WEBHOOK;
27	  if (webhook && level === "error") {
28	    try {
29	      await fetch(webhook, {
30	        method: "POST",
31	        headers: { "content-type": "application/json" },
32	        body: JSON.stringify({ text: `🚨 Nxeon ${context}: ${detail.message ?? "error"}`, detail: line }),
33	        signal: AbortSignal.timeout(3000),
34	      });
35	    } catch {
36	      // never let logging throw
37	    }
38	  }
39	}
40	
41	export function logError(context: string, error: unknown, extra: Record<string, unknown> = {}) {
42	  const e = error as { message?: string; stack?: string; digest?: string };
43	  return logEvent("error", context, {
44	    message: e?.message ?? String(error),
45	    stack: e?.stack?.split("\n").slice(0, 6).join("\n"),
46	    digest: e?.digest,
47	    ...extra,
48	  });
49	}
