import { NextResponse } from "next/server";
import { getHealth, type CompStatus, type HealthReport } from "@/lib/monitoring";

export const dynamic = "force-dynamic";
export const runtime = "nodejs";

/**
 * GET /api/health — public, unauthenticated health probe.
 *
 * Returns { web, db, worker, proxmox } where each is
 * { status: "operational" | "degraded" | "down", detail }.
 *
 * IMPORTANT: `getHealth()` embeds raw upstream error text in component details
 * (e.g. DB connection strings / auth-failure messages, internal host:port).
 * Because this endpoint is unauthenticated we NEVER pass those through — each
 * component is mapped to a coarse public status and a generic, secret-free
 * detail string before responding.
 *
 * Cached ~15s in-process so external monitors / the status page don't hammer
 * the DB and Proxmox on every request.
 */

const TTL_MS = 15_000;
let cache: { at: number; body: HealthReport } | null = null;

/** Fixed, secret-free copy per component + status. Never derived from upstream text. */
const PUBLIC_DETAIL: Record<CompStatus, string> = {
  operational: "operational",
  degraded: "degraded",
  down: "unavailable",
};

type PublicComponent = { status: CompStatus; detail: string };
type PublicHealth = {
  web: PublicComponent;
  db: PublicComponent;
  worker: PublicComponent;
  proxmox: PublicComponent;
  checkedAt: string;
};

function sanitize(report: HealthReport): PublicHealth {
  const pub = (status: CompStatus): PublicComponent => ({ status, detail: PUBLIC_DETAIL[status] });
  return {
    web: pub(report.web.status),
    db: pub(report.db.status),
    worker: pub(report.worker.status),
    proxmox: pub(report.proxmox.status),
    checkedAt: report.checkedAt,
  };
}

export async function GET() {
  try {
    if (!cache || Date.now() - cache.at > TTL_MS) {
      cache = { at: Date.now(), body: await getHealth() };
    }
    const worstDown =
      cache.body.db.status === "down" || cache.body.proxmox.status === "down";
    return NextResponse.json(sanitize(cache.body), {
      status: worstDown ? 503 : 200,
      headers: { "Cache-Control": "public, max-age=15, s-maxage=15" },
    });
  } catch {
    // Never leak the underlying failure text to an unauthenticated caller.
    return NextResponse.json({ error: "health check failed" }, { status: 500 });
  }
}

